<?php declare(strict_types=1);use Kulturhus\Verein\Inventory;$returnData=$loanFormData('return');$returnRows=array_values(array_filter($loan['lines'],static fn(array$r):bool=>$r['quantity']>$r['returned']+$r['lost'])); ?>
<form method="post" class="card iv-no-print" action="<?= e($loanFormUrl('return')) ?>" id="inventory-loan-return" data-loan-operation="return"><?= $loanHeader('return') ?><h2><?= e($loanActionText('Rückgabe / Teilrückgabe erfassen')) ?></h2><p><?= e($loanActionText('Nur vollständige Einheiten oder Sätze zählen. Fehlende Bestandteile im Zustandsvermerk nennen. Unvollständige zurückgegebene Sätze können beschädigt gesperrt werden; draußen gebliebene Sätze bleiben offen. Kein automatischer Verlust eines ganzen Satzes.')) ?></p>
<?php foreach($returnRows as$position=>$line):$open=$line['quantity']-$line['returned']-$line['lost'];$returnLine=[];foreach(($returnData['lines']??[])as$candidate)if($candidate['line']===$line['id']){$returnLine=$candidate;break;}$prefix='data[lines]['.$position.']'; ?>
<fieldset class="iv-loan-return-line" data-loan-return-line><legend><?= e($loanActionText('Position {number}: {name}',['number'=>(string)($position+1),'name'=>$line['item_name']])) ?></legend><?= hidden($prefix.'[line]',$line['id']) ?><p><?= e($line['item_code']) ?> · <?= e($loanActionText('Noch offen')) ?>: <?= e(Inventory::contentSummary($line,(int)$open,$loanActionText)?:$open.' '.$line['unit']) ?></p>
<div class="iv-form-grid"><?php foreach(['good'=>'Vollständige Einheiten / Sätze zurück','damaged'=>'Beschädigt / unvollständig zurück','lost'=>'Ganze Einheiten verloren']as$field=>$caption): ?><label><?= e($loanActionText($caption)) ?><input class="form-control" type="number" name="<?= e($prefix.'['.$field.']') ?>" min="0" max="<?= $open ?>" step="1" value="<?= e($returnLine[$field]??'0') ?>" required></label><?php endforeach ?><label><?= e($loanActionText('Tatsächlicher Rückgabeort')) ?><select class="form-control" name="<?= e($prefix.'[location]') ?>"><?php $returnLocations=\Kulturhus\Verein\Web\InventoryCatalogueForm::options($locationOptions,$returnLine['location']??'',$loanActionText('Ausgewählter Lagerort nicht mehr verfügbar – bitte neu auswählen'));foreach($returnLocations as$id=>$caption): ?><option value="<?= e($id) ?>" <?= ($returnLine['location']??'')===(string)$id?'selected':'' ?>><?= e($caption) ?></option><?php endforeach ?></select></label></div>
<?php $units=$inventory->purchaseUnits($line['item_id']);if($units):$selected=$returnLine['purchase_unit_ids']??[]; ?><details class="iv-loan-return-pieces" <?= $selected?'open':'' ?>><summary><?= e($loanActionText('Verlorene Stücke ausdrücklich auswählen')) ?></summary><p><?= e($loanActionText('Nur tatsächlich verlorene Stücke markieren. Für eine vollständige Entfernung aller Stücke dieses Gegenstands ist keine einzelne Auswahl nötig. Preise und Rechnungen ändern sich durch die Auswahl nicht.')) ?></p><?php foreach($units as$unit): ?><label class="check"><input type="checkbox" name="<?= e($prefix.'[purchase_unit_ids][]') ?>" value="<?= e($unit['id']) ?>" <?= in_array($unit['id'],$selected,true)?'checked':'' ?>><span class="iv-loan-piece-caption"><?= e($loanActionText('Stück {number}',['number'=>(string)$unit['sequence']])) ?><?php if(($unit['serial_number']??'')!==''): ?> · <?= e($loanActionText('Seriennummer: {serial}',['serial'=>$unit['serial_number']])) ?><?php endif ?></span></label><?php endforeach ?></details><?php endif ?></fieldset>
<?php endforeach ?>
<div class="iv-form-grid"><?php $loanField('data[date]','Rückgabedatum',$returnData['date']??Inventory::today(),'date');$loanField('data[reason]','Zustand / Schäden / Verlustbegründung',$returnData['reason']??'','textarea'); ?></div><button class="btn btn-solid theme-primary"><?= e($loanActionText('Rückgabe bestätigen')) ?></button><?= hidden('loan_action_complete','1') ?></form>
